const API_URL = "http://localhost:3000/anime";

fetch(API_URL)
  .then((response) => {
    if (!response.ok) {
      throw new Error(`Erreur réseau: ${response.status}`);
    }
    return response.json();
  })
  .then((data) => {
    console.log("Base d'anime reçue :", data);
  })
  .catch((error) => {
    console.error("Erreur lors de la récupération :", error);
  });
